// Package security provides HTTP middleware for setting day-1 security headers
// on every response.
package security

import "net/http"

// Middleware returns an http.Handler middleware that sets the day-1 security
// headers on every response. It sets:
//   - Strict-Transport-Security (HSTS)
//   - X-Content-Type-Options
//   - X-Frame-Options
//   - Referrer-Policy
//
// CSP is omitted here because it differs between the BFF (API-only, no HTML)
// and the nginx static-asset servers. Add CSP at the nginx layer or via a
// dedicated middleware wrapping only HTML-serving routes.
func Middleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
		w.Header().Set("X-Content-Type-Options", "nosniff")
		w.Header().Set("X-Frame-Options", "DENY")
		w.Header().Set("Referrer-Policy", "strict-origin-when-cross-origin")
		next.ServeHTTP(w, r)
	})
}


