package security

import (
	"errors"
	"fmt"
	"io"
	"mime"
	"net/http"
	"path/filepath"
	"strings"
)

// ErrUnsupportedMediaType is returned by [ResolveUploadMIME] when neither
// the client-declared MIME type, the sniffed content, nor the filename
// extension resolves to a type the given [UploadPolicy] allows. Callers
// MUST map this to HTTP 415 (Unsupported Media Type) — never 400, which
// already means "malformed multipart" upstream of this package.
var ErrUnsupportedMediaType = errors.New("security: unsupported media type")

// UploadPolicy selects which set of MIME types an upload surface accepts.
// Each policy is a distinct, independently justified allowlist — never a
// union or bitmask of one shared set — because the surfaces it gates carry
// different risk: general file storage, chat attachments meant for inline
// preview, and document text-extraction all have different legitimate
// inputs.
type UploadPolicy int

const (
	// FilesUploadPolicy is the general-purpose files-bff upload surface:
	// documents, images, audio voice samples, and the vendor markdown
	// profile/post types the frontend DocumentPickerModal discriminates
	// on.
	FilesUploadPolicy UploadPolicy = iota
	// DialogueAttachmentPolicy is the narrower policy for chat-style
	// dialogue attachments: images meant for inline preview, plus PDF and
	// plain/markdown/CSV text. No audio, no DOCX, no vendor markdown
	// types, no bare octet-stream — an attachment surface has no reason to
	// accept an opaque binary blob.
	DialogueAttachmentPolicy
	// StudioExtractPolicy is Studio's document-extraction policy: images
	// plus the document formats its extractor actually parses (PDF, DOCX,
	// text, markdown, CSV). Deliberately excludes audio — extraction has
	// no audio pipeline — which is what distinguishes it from
	// FilesUploadPolicy.
	StudioExtractPolicy
)

// docxMIME is the canonical MIME type for a Word .docx document. DOCX files
// are zip containers, so http.DetectContentType sniffs them as
// "application/zip" — a definite detection that a naked policy check would
// reject. See the docx special case in [ResolveUploadMIME].
const docxMIME = "application/vnd.openxmlformats-officedocument.wordprocessingml.document"

// canonicalAliases maps a raw, non-canonical MIME type (as produced by
// http.DetectContentType, or as sent by a less careful client) to the
// canonical type this package's allowlists are keyed on. Applied by
// [NormalizeMediaType] to BOTH the declared and the detected value, so
// aliasing happens before any allowlist check.
//
// audio/wave -> audio/wav is load-bearing: Go's sniffer returns
// "audio/wave" for a WAV file (see $GOROOT/src/net/http/sniff.go), and it
// is a definite detection. Voice-sample uploads declare "audio/wav".
// Without this alias, every voice-sample upload would 415.
var canonicalAliases = map[string]string{
	"audio/wave":      "audio/wav",
	"audio/x-wav":     "audio/wav",
	"audio/vnd.wave":  "audio/wav",
	"audio/x-flac":    "audio/flac",
	"application/ogg": "audio/ogg",
}

// alwaysRejected lists MIME types that must never resolve successfully
// under ANY policy, checked explicitly against the (normalized) declared
// type whenever detection is indefinite. Detection being definite already
// rejects these on its own (none of them appear in any allowlist below),
// but an indefinite detection (e.g. an SVG or a shell script, both of
// which are plain text and sniff as text/plain) would otherwise be able to
// fall through to the extension map or the application/octet-stream
// rescue — this check closes that gap.
var alwaysRejected = map[string]bool{
	"image/svg+xml":             true,
	"text/html":                 true,
	"text/xml":                  true,
	"application/xml":           true,
	"application/xhtml+xml":     true,
	"text/x-sh":                 true,
	"application/x-sh":          true,
	"application/x-shellscript": true,
	"application/msword":        true,
}

// inlineSafe is the set of MIME types safe to serve with a
// Content-Disposition of "inline". Deliberately excludes image/svg+xml,
// which can carry script content and must never be rendered inline.
var inlineSafe = map[string]bool{
	"image/png":  true,
	"image/jpeg": true,
	"image/gif":  true,
	"image/webp": true,
	"image/bmp":  true,
}

// filesUploadAllowed is the FilesUploadPolicy allowlist: the inline-safe
// image set, common document formats, the DOCX type, TIFF (not
// inline-safe — no browser renders it inline), RTF, voice-sample audio
// formats, the three vendor markdown discriminator types, and bare
// application/octet-stream. octet-stream is safe here specifically
// because it is attachment-only on the serve side (see [ServeDisposition]),
// so it is not an inline-render vector.
var filesUploadAllowed = unionSets(inlineSafe, map[string]bool{
	"application/pdf":  true,
	"text/plain":       true,
	"text/markdown":    true,
	"text/csv":         true,
	"application/json": true,
	"application/yaml": true,
	"text/yaml":        true,
	docxMIME:           true,
	"image/tiff":       true,
	"application/rtf":  true,
	"text/rtf":         true,
	"audio/wav":        true,
	"audio/mpeg":       true,
	"audio/flac":       true,
	"audio/ogg":        true,
	"audio/aiff":       true,
	"text/vnd.omnicore.brand-profile+markdown":    true,
	"text/vnd.omnicore.audience-profile+markdown": true,
	"text/vnd.omnicore.content-post+markdown":     true,
	"application/octet-stream":                    true,
})

// dialogueAttachmentAllowed is the DialogueAttachmentPolicy allowlist:
// inline-safe images plus the text/document formats worth previewing in a
// chat thread. No audio, no DOCX, no vendor markdown, no octet-stream.
var dialogueAttachmentAllowed = unionSets(inlineSafe, map[string]bool{
	"application/pdf": true,
	"text/plain":      true,
	"text/markdown":   true,
	"text/csv":        true,
})

// studioExtractAllowed is the StudioExtractPolicy allowlist: inline-safe
// images plus the document formats Studio's text extractor parses.
// Deliberately excludes audio (extraction has no audio pipeline) and
// vendor markdown/octet-stream (extraction always knows its own input
// type).
var studioExtractAllowed = unionSets(inlineSafe, map[string]bool{
	"application/pdf": true,
	docxMIME:          true,
	"text/plain":      true,
	"text/markdown":   true,
	"text/csv":        true,
})

// uploadPolicySets maps each [UploadPolicy] to its allowlist.
var uploadPolicySets = map[UploadPolicy]map[string]bool{
	FilesUploadPolicy:        filesUploadAllowed,
	DialogueAttachmentPolicy: dialogueAttachmentAllowed,
	StudioExtractPolicy:      studioExtractAllowed,
}

// extensionMIME is a HARDCODED filename-extension-to-MIME map, used only
// as the second fallback (after declared-if-allowlisted) when
// http.DetectContentType returns an indefinite result. Deliberately not
// mime.TypeByExtension, which reads /etc/mime.types and is
// platform-dependent.
var extensionMIME = map[string]string{
	".pdf":  "application/pdf",
	".txt":  "text/plain",
	".md":   "text/markdown",
	".csv":  "text/csv",
	".json": "application/json",
	".yaml": "application/yaml",
	".yml":  "application/yaml",
	".docx": docxMIME,
	".tiff": "image/tiff",
	".tif":  "image/tiff",
	".rtf":  "application/rtf",
	".wav":  "audio/wav",
	".mp3":  "audio/mpeg",
	".flac": "audio/flac",
	".ogg":  "audio/ogg",
	".aiff": "audio/aiff",
	".aif":  "audio/aiff",
}

// unionSets returns a new map containing every key from every argument.
func unionSets(sets ...map[string]bool) map[string]bool {
	out := make(map[string]bool)
	for _, set := range sets {
		for k, v := range set {
			out[k] = v
		}
	}
	return out
}

// NormalizeMediaType strips any MIME parameters (e.g. "; charset=utf-8"),
// lowercases the result, and applies [canonicalAliases]. Used uniformly on
// both the client-declared type and the http.DetectContentType result, so
// aliasing always happens before any allowlist comparison.
func NormalizeMediaType(s string) string {
	mt, _, err := mime.ParseMediaType(s)
	if err != nil {
		// s has no parseable parameters (or is malformed/empty). Fall back
		// to a best-effort strip-and-lowercase of the bare type instead of
		// discarding it outright.
		mt = strings.ToLower(strings.TrimSpace(strings.SplitN(s, ";", 2)[0]))
	}
	if alias, ok := canonicalAliases[mt]; ok {
		return alias
	}
	return mt
}

// isDefiniteDetection reports whether an http.DetectContentType result (as
// already normalized by [NormalizeMediaType]) is a definite, specific
// detection rather than one of the two indefinite fallbacks
// http.DetectContentType itself falls back to.
func isDefiniteDetection(mt string) bool {
	return mt != "text/plain" && mt != "application/octet-stream"
}

// hasExtension reports whether filename ends in ext (case-insensitively).
func hasExtension(filename, ext string) bool {
	return strings.EqualFold(filepath.Ext(filename), ext)
}

// ResolveUploadMIME resolves the canonical MIME type of an upload under the
// given policy, or returns [ErrUnsupportedMediaType].
//
// Resolution order:
//  1. Normalize the declared type and sniff head (capped at 512 bytes)
//     via http.DetectContentType.
//  2. If the sniff is DEFINITE (i.e. not text/plain and not
//     application/octet-stream), it wins outright: apply the alias map,
//     then check it against the policy's allowlist. A non-allowlisted
//     definite detection is rejected — this is what catches an SVG or
//     HTML file renamed to a trusted extension. The one exception is
//     application/zip detected alongside a .docx filename, which coerces
//     to the DOCX MIME type; a bare zip with no .docx filename rejects.
//  3. If the sniff is INDEFINITE (text/plain* or octet-stream), fall back
//     in this exact order:
//     a. the normalized declared type, if it is allowlisted for policy
//     (checked first, and before this, an explicit denylist check on
//     the declared type — this ordering is what lets a vendor markdown
//     type such as text/vnd.omnicore.brand-profile+markdown survive a
//     .md filename instead of being silently rewritten by the
//     extension map);
//     b. the hardcoded extension map, keyed on the filename extension;
//     c. text/plain, if the sniff itself detected text/plain (as opposed
//     to the other indefinite result, application/octet-stream) and
//     text/plain is allowlisted for policy — this is what lets an
//     unlabeled plain-text body with no matching extension resolve to
//     the accurate text/plain instead of being discarded. (Checking
//     specifically for text/plain rather than the detected value in
//     general is not a narrowing: the indefinite branch's only other
//     possible detected value is application/octet-stream, for which
//     this check would be identical to step d below.)
//     d. application/octet-stream, if allowlisted for policy.
func ResolveUploadMIME(policy UploadPolicy, declared string, filename string, head []byte) (string, error) {
	if len(head) > 512 {
		head = head[:512]
	}
	allowed := uploadPolicySets[policy]

	detected := NormalizeMediaType(http.DetectContentType(head))
	if isDefiniteDetection(detected) {
		if detected == "application/zip" && hasExtension(filename, ".docx") {
			if allowed[docxMIME] {
				return docxMIME, nil
			}
			return "", ErrUnsupportedMediaType
		}
		if allowed[detected] {
			return detected, nil
		}
		return "", ErrUnsupportedMediaType
	}

	declaredNormalized := NormalizeMediaType(declared)
	if alwaysRejected[declaredNormalized] {
		return "", ErrUnsupportedMediaType
	}
	if allowed[declaredNormalized] {
		return declaredNormalized, nil
	}
	if mt, ok := extensionMIME[strings.ToLower(filepath.Ext(filename))]; ok && allowed[mt] {
		return mt, nil
	}
	if detected == "text/plain" && allowed[detected] {
		return detected, nil
	}
	if allowed["application/octet-stream"] {
		return "application/octet-stream", nil
	}
	return "", ErrUnsupportedMediaType
}

// PeekHead reads up to 512 bytes from the start of r (enough for
// http.DetectContentType, which never looks past 512 bytes) and rewinds r
// back to its start via Seek. multipart.File's io.Seeker is unconditional
// (every implementation backs onto either an in-memory buffer or an
// *os.File), so no bufio/TeeReader/MultiReader dance is needed here — a
// plain read-then-seek suffices.
//
// A failed rewind is returned as an error rather than swallowed: silently
// ignoring it would leave r positioned up to 512 bytes into the stream,
// truncating the upload for whatever reads r next.
func PeekHead(r io.ReadSeeker) ([]byte, error) {
	buf := make([]byte, 512)
	n, err := io.ReadFull(r, buf)
	if err != nil && !errors.Is(err, io.ErrUnexpectedEOF) && !errors.Is(err, io.EOF) {
		return nil, fmt.Errorf("security: reading upload head: %w", err)
	}
	if _, err := r.Seek(0, io.SeekStart); err != nil {
		return nil, fmt.Errorf("security: rewinding upload after head peek: %w", err)
	}
	return buf[:n], nil
}

// IsInlineSafe reports whether mt (after normalization) is safe to serve
// with a Content-Disposition of "inline" — i.e. it is one of the raster
// image types in [inlineSafe]. Notably false for image/svg+xml, which can
// carry executable script content.
func IsInlineSafe(mt string) bool {
	return inlineSafe[NormalizeMediaType(mt)]
}

// ServeDisposition returns the Content-Disposition value ("inline" or
// "attachment") a caller should serve mt with.
func ServeDisposition(mt string) string {
	if IsInlineSafe(mt) {
		return "inline"
	}
	return "attachment"
}


