	svgHead := []byte("<?xml version=\"1.0\"?><svg xmlns=\"http://www.w3.org/2000/svg\"></svg>")
	_, err := ResolveUploadMIME(FilesUploadPolicy, "image/png", "photo.png", svgHead)
