//
// Empty and whitespace-only tokens (from stray/duplicate commas, or an
// empty input string) are skipped rather than erroring — this keeps a
// trailing comma in an env var harmless. Any token that is neither a valid
// CIDR nor a valid bare IP address is a hard configuration error: silently
// dropping it would shrink the trust set in a way nobody asked for.
func ParseTrustedProxyCIDRs(raw string) ([]netip.Prefix, error) {
	var prefixes []netip.Prefix
	for _, tok := range strings.Split(raw, ",") {
		tok = strings.TrimSpace(tok)
		if tok == "" {
			continue
		}
		prefix, err := parseCIDROrBareIP(tok)
		if err != nil {
			return nil, fmt.Errorf("security: invalid trusted proxy CIDR %q: %w", tok, err)
		}
		prefixes = append(prefixes, prefix)
	}
	return prefixes, nil
}

// parseCIDROrBareIP parses tok as a CIDR prefix, or — if it carries no
// "/" — as a bare IP address widened to a single-address prefix (/32 for
// IPv4, /128 for IPv6).
func parseCIDROrBareIP(tok string) (netip.Prefix, error) {
	if strings.Contains(tok, "/") {
		return netip.ParsePrefix(tok)
	}
	addr, err := netip.ParseAddr(tok)
	if err != nil {
		return netip.Prefix{}, err
	}
	bits := 32
	if addr.Is6() {
		bits = 128
	}
	return netip.PrefixFrom(addr, bits), nil
}

// ClientIPMiddleware sets the request's client IP in context (readable via
// [ClientIP]), trusting the X-Forwarded-For chain ONLY when the immediate
// peer (r.RemoteAddr) itself falls within one of the given trusted proxy
// CIDRs. This closes the gap that chi's own ClientIPFromXFF leaves open:
// that middleware trusts XFF unconditionally, so a caller that dials a
// host-published port directly — bypassing every real proxy — can hand-roll
// an X-Forwarded-For header and have it honored verbatim.
//
// Two composed chains are built once, up front, using only chi's exported
// ClientIPFrom* middlewares (chi's client-IP context key is unexported, so
// there is no way to set it directly):
//
//   - RemoteAddr trusted: middleware.ClientIPFromXFF walks the chain
//     right-to-left, skipping trusted hops, and stops at the first
//     untrusted entry (or leaves no IP set if every entry is trusted, or
//     the chain is empty, or an entry fails to parse).
//   - RemoteAddr untrusted (or unparseable): middleware.ClientIPFromRemoteAddr
//     is used and XFF is never inspected — the direct peer address is
//     always the answer, so a spoofed XFF header cannot influence it.
//
// Callers should read the result through [ClientIP], which additionally
// falls back to RemoteAddr whenever the trusted-hop XFF walk above leaves
// no IP set (all-trusted chain, empty chain, or unparseable entry) — the
// nearest trusted address is a better answer than no answer.
func ClientIPMiddleware(trusted []netip.Prefix) func(http.Handler) http.Handler {
	trustedStrs := make([]string, len(trusted))
	for i, p := range trusted {
		trustedStrs[i] = p.String()
	}
	viaXFF := middleware.ClientIPFromXFF(trustedStrs...)

	return func(next http.Handler) http.Handler {
		xffHandler := viaXFF(next)
		remoteAddrHandler := middleware.ClientIPFromRemoteAddr(next)

		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if remoteAddrIsTrusted(r, trusted) {
				xffHandler.ServeHTTP(w, r)
				return
			}
			remoteAddrHandler.ServeHTTP(w, r)
		})
	}
}

// remoteAddrIsTrusted reports whether r.RemoteAddr's host component parses
// as an IP and falls within one of the trusted prefixes. An unparseable
// RemoteAddr, or an empty trust set, is never trusted.
func remoteAddrIsTrusted(r *http.Request, trusted []netip.Prefix) bool {
	addr, ok := parseRemoteAddr(r.RemoteAddr)
	if !ok {
		return false
	}
	for _, p := range trusted {
		if p.Contains(addr) {
			return true
		}
	}
	return false
}

// parseRemoteAddr parses an http.Request.RemoteAddr, which is normally
// "host:port" but may be a bare IP (as httptest.NewRequest leaves it, and
// as some direct connections present it).
func parseRemoteAddr(remoteAddr string) (netip.Addr, bool) {
	host, _, err := net.SplitHostPort(remoteAddr)
	if err != nil {
		host = remoteAddr
	}
	addr, err := netip.ParseAddr(host)
	if err != nil {
		return netip.Addr{}, false
	}
	return addr.Unmap(), true
}

// ClientIP returns the request's client IP as a string: whatever
// [ClientIPMiddleware] set in context, or — if that middleware left no IP
// set — a fallback to r.RemoteAddr. Returns "" only if neither source
// yields a parseable address.
func ClientIP(r *http.Request) string {
	if ip := middleware.GetClientIP(r.Context()); ip != "" {
		return ip
	}
	addr, ok := parseRemoteAddr(r.RemoteAddr)
	if !ok {
		return ""
	}
	return addr.String()
}

// errNoClientIP is returned by [KeyByIP] (and the key funcs built on it)
// when no client IP can be resolved for the request, so callers never
// silently collapse into one shared "" bucket.
var errNoClientIP = errors.New("security: no client IP available for rate-limit key")

// KeyByIP is an httprate KeyFunc that buckets requests by [ClientIP]. Unlike
// httprate.KeyByIP, it is trusted-proxy aware when composed behind
// [ClientIPMiddleware], and it returns a non-nil error instead of "" when
// no IP can be resolved — an empty key would otherwise bucket every
// unresolvable request together.
func KeyByIP(r *http.Request) (string, error) {
	ip := ClientIP(r)
	if ip == "" {
		return "", errNoClientIP
	}
	return ip, nil
}

// KeyByURLParamAndIP returns an httprate KeyFunc that buckets requests by
// (chi URL param value, ClientIP) — e.g. rate-limiting per (org slug, IP)
// on routes where the tenant isn't yet resolved to claims.
func KeyByURLParamAndIP(param string) func(*http.Request) (string, error) {
	return func(r *http.Request) (string, error) {
		val := chi.URLParam(r, param)
		ip, err := KeyByIP(r)
		return val + ":" + ip, err
	}
}

// LimitByClientIP returns rate-limit middleware keyed by [KeyByIP] —
// trusted-proxy-aware client IP, requestLimit requests per windowLength.
func LimitByClientIP(requestLimit int, windowLength time.Duration) func(http.Handler) http.Handler {
	return httprate.Limit(requestLimit, windowLength, httprate.WithKeyFuncs(KeyByIP))
}


