package security

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestMiddleware_SetsAllHeaders(t *testing.T) {
	handler := Middleware(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
	}))

	req := httptest.NewRequest("GET", "/", nil)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)

	cases := map[string]string{
		"Strict-Transport-Security": "max-age=31536000; includeSubDomains",
		"X-Content-Type-Options":    "nosniff",
		"X-Frame-Options":           "DENY",
		"Referrer-Policy":           "strict-origin-when-cross-origin",
	}
	for header, expected := range cases {
		if got := rec.Header().Get(header); got != expected {
			t.Errorf("header %s: got %q, want %q", header, got, expected)
		}
	}
}

func TestMiddleware_PreservesNextHandler(t *testing.T) {
	called := false
	handler := Middleware(http.HandlerFunc(func(_ http.ResponseWriter, _ *http.Request) {
		called = true
	}))
	handler.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", "/", nil))
	if !called {
		t.Error("next handler not called")
	}
}

func TestMiddleware_SetsHeadersBeforeNextHandler(t *testing.T) {
	// Verify headers are present when the next handler runs (not after).
	var gotHSTS string
	handler := Middleware(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		gotHSTS = w.Header().Get("Strict-Transport-Security")
	}))
	handler.ServeHTTP(httptest.NewRecorder(), httptest.NewRequest("GET", "/healthz", nil))
	if gotHSTS != "max-age=31536000; includeSubDomains" {
		t.Errorf("HSTS not visible inside next handler: got %q", gotHSTS)
	}
}

func TestMiddleware_DifferentMethods(t *testing.T) {
	methods := []string{http.MethodGet, http.MethodPost, http.MethodPut, http.MethodDelete, http.MethodOptions}
	for _, method := range methods {
		t.Run(method, func(t *testing.T) {
			handler := Middleware(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
				w.WriteHeader(http.StatusOK)
			}))
			rec := httptest.NewRecorder()
			handler.ServeHTTP(rec, httptest.NewRequest(method, "/test", nil))
			if got := rec.Header().Get("X-Content-Type-Options"); got != "nosniff" {
				t.Errorf("method %s: X-Content-Type-Options = %q, want %q", method, got, "nosniff")
			}
		})
	}
}


