func TestPeekHead_ReadsUpTo512BytesAndRewinds(t *testing.T) {
	content := append([]byte("%PDF-1.4\n"), bytes.Repeat([]byte("y"), 1024)...)
	r := bytes.NewReader(content)

	head, err := PeekHead(r)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(head) != 512 {
		t.Errorf("got head length %d, want %d", len(head), 512)
	}
	if !bytes.Equal(head, content[:512]) {
		t.Error("head does not match first 512 bytes of content")
	}

	rest, err := io.ReadAll(r)
	if err != nil {
		t.Fatalf("unexpected error reading rest: %v", err)
	}
	if !bytes.Equal(rest, content) {
		t.Error("reader was not rewound to the start after PeekHead")
	}
}

