// failingSeeker returns an error from Seek to exercise PeekHead's rewind
// failure path, which must never be swallowed (a swallowed rewind failure
// truncates the upload for every downstream reader).
type failingSeeker struct {
	*bytes.Reader
}

func (f *failingSeeker) Seek(offset int64, whence int) (int64, error) {
	return 0, errors.New("boom: seek failed")
}

func TestPeekHead_FailedRewindIsReturnedAsError(t *testing.T) {
	fs := &failingSeeker{bytes.NewReader([]byte("some content"))}
	_, err := PeekHead(fs)
	if err == nil {
		t.Fatal("expected an error when Seek fails, got nil")
	}
	if !strings.Contains(err.Error(), "boom: seek failed") {
		t.Errorf("error %q does not wrap the underlying seek error", err.Error())
	}
}

// failingReader returns an error from Read (not just EOF) to exercise
// PeekHead's read failure path.
type failingReader struct{}

func (failingReader) Read(_ []byte) (int, error)         { return 0, errors.New("boom: read failed") }
func (failingReader) Seek(_ int64, _ int) (int64, error) { return 0, nil }

func TestPeekHead_ReadFailureIsReturnedAsError(t *testing.T) {
	_, err := PeekHead(failingReader{})
	if err == nil {
		t.Fatal("expected an error when Read fails, got nil")
	}
	if !strings.Contains(err.Error(), "boom: read failed") {
		t.Errorf("error %q does not wrap the underlying read error", err.Error())
	}
}

