package security

import (
	"net/http"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
)

// KeyByOrgIDAndIP is an httprate KeyFunc that buckets requests by
// (claims.OrgID, RealIP). Pre-auth endpoints (login, callback, refresh)
// where claims are not yet attached to the context fall back to ":<ip>"
// — the IP-only form — which is exactly what we want: those routes are
// rate-limited per source address regardless of who the caller will turn
// out to be.
//
// The combined key prevents two failure modes:
//
//  1. A noisy legitimate tenant burning through the limiter and starving
//     other tenants on shared infrastructure (org_id alone, single IP
//     pool).
//  2. A single attacker on a fixed IP making many requests as different
//     authenticated users (IP alone — the bucket would refresh per user).
//
// T1.7 from the 2026-05-05 foundation-readiness review. Used by both
// shell-bff and admin-bff routers.
func KeyByOrgIDAndIP(r *http.Request) (string, error) {
	var orgID string
	if claims, ok := auth.ClaimsFromContext(r.Context()); ok {
		orgID = claims.OrgID
	}
	// KeyByIP is trusted-proxy aware (see clientip.go) and returns a
	// non-nil error rather than "" when no client IP can be resolved, so
	// that failure never collapses into one shared "org:" bucket.
	ip, err := KeyByIP(r)
	return orgID + ":" + ip, err
}


