package security

import (
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/go-chi/httprate"
	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
)

func TestKeyByOrgIDAndIP_AnonymousRequest(t *testing.T) {
	// No claims attached — pre-auth path (e.g., /api/v1/auth/login).
	// Key must still produce a deterministic value so the limiter
	// throttles per source address.
	r := httptest.NewRequest(http.MethodGet, "/", nil)
	r.RemoteAddr = "203.0.113.7:54321"

	key, err := KeyByOrgIDAndIP(r)
	require.NoError(t, err)
	require.Equal(t, ":203.0.113.7", key,
		"anonymous requests must bucket by IP only — empty org_id prefix preserves the field separator")
}

func TestKeyByOrgIDAndIP_AuthenticatedRequest(t *testing.T) {
	r := httptest.NewRequest(http.MethodGet, "/", nil)
	r.RemoteAddr = "198.51.100.42:1234"
	ctx := auth.ClaimsIntoContext(r.Context(), auth.Claims{
		Subject: "u-1",
		OrgID:   "org-acme",
	})

	key, err := KeyByOrgIDAndIP(r.WithContext(ctx))
	require.NoError(t, err)
	require.Equal(t, "org-acme:198.51.100.42", key)
}

func TestKeyByOrgIDAndIP_DifferentOrgs_GetSeparateBuckets(t *testing.T) {
	// Two requests from the same IP but different tenants must produce
	// different keys. This is the core scaling property of the keyer:
	// one tenant's traffic doesn't drain another tenant's bucket.
	mk := func(orgID string) string {
		r := httptest.NewRequest(http.MethodGet, "/", nil)
		r.RemoteAddr = "192.0.2.1:9999"
		ctx := auth.ClaimsIntoContext(r.Context(), auth.Claims{OrgID: orgID})
		key, err := KeyByOrgIDAndIP(r.WithContext(ctx))
		require.NoError(t, err)
		return key
	}
	require.NotEqual(t, mk("org-a"), mk("org-b"))
}

func TestKeyByOrgIDAndIP_SameOrgDifferentIPs_GetSeparateBuckets(t *testing.T) {
	// Conversely, two requests for the same tenant from different IPs
	// must NOT share a bucket — otherwise an attacker could exhaust the
	// tenant's limiter from a botnet.
	mk := func(remote string) string {
		r := httptest.NewRequest(http.MethodGet, "/", nil)
		r.RemoteAddr = remote
		ctx := auth.ClaimsIntoContext(r.Context(), auth.Claims{OrgID: "org-acme"})
		key, err := KeyByOrgIDAndIP(r.WithContext(ctx))
		require.NoError(t, err)
		return key
	}
	require.NotEqual(t, mk("192.0.2.1:1"), mk("192.0.2.2:1"))
}

// TestKeyByOrgIDAndIP_HttprateIntegration proves the keyer is wire-
// compatible with the actual httprate.Limit middleware shape used by
// both BFFs: requests below the limit return 200, the (limit+1)th
// returns 429, and a different bucket is unaffected.
func TestKeyByOrgIDAndIP_HttprateIntegration(t *testing.T) {
	const limit = 3

	h := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
	})
	limited := httprate.Limit(limit, time.Minute,
		httprate.WithKeyFuncs(KeyByOrgIDAndIP))(h)

	// Same (org, IP): first `limit` requests OK, then 429.
	for i := 0; i < limit; i++ {
		req := httptest.NewRequest(http.MethodGet, "/", nil)
		req.RemoteAddr = "203.0.113.1:1"
		req = req.WithContext(auth.ClaimsIntoContext(req.Context(),
			auth.Claims{OrgID: "org-1"}))
		w := httptest.NewRecorder()
		limited.ServeHTTP(w, req)
		require.Equal(t, http.StatusOK, w.Code, "request %d under the limit must succeed", i+1)
	}

	overReq := httptest.NewRequest(http.MethodGet, "/", nil)
	overReq.RemoteAddr = "203.0.113.1:1"
	overReq = overReq.WithContext(auth.ClaimsIntoContext(overReq.Context(),
		auth.Claims{OrgID: "org-1"}))
	w := httptest.NewRecorder()
	limited.ServeHTTP(w, overReq)
	require.Equal(t, http.StatusTooManyRequests, w.Code,
		"request limit+1 from the same (org, IP) must be rejected with 429")

	// A different tenant from the same IP is in its own bucket, so its
	// first request must succeed even though org-1 is rate-limited.
	otherReq := httptest.NewRequest(http.MethodGet, "/", nil)
	otherReq.RemoteAddr = "203.0.113.1:1"
	otherReq = otherReq.WithContext(auth.ClaimsIntoContext(otherReq.Context(),
		auth.Claims{OrgID: "org-2"}))
	w = httptest.NewRecorder()
	limited.ServeHTTP(w, otherReq)
	require.Equal(t, http.StatusOK, w.Code,
		"a separate (org, IP) bucket must be unaffected by another tenant's saturated bucket")
}



